with products_by_supplier as (select supplier_id, sum(case when brand = 'Initech' then 1 else 0 end) as initech_count, count(case when category = 'Grocery' then 1 end) as grocery_count from products group by supplier_id) select suppliers.supplier_name, suppliers.country, products_by_supplier.initech_count, products_by_supplier.grocery_count from suppliers left join products_by_supplier on suppliers.id = products_by_supplier.supplier_id where products_by_supplier.grocery_count > 4 order by suppliers.supplier_name, products_by_supplier.initech_count desc;
